oxy_webhelp_navlinks = {"ms_copilot_studio_agent_operations-d36754e60146":{"topics":[{"title":"Microsoft Copilot Studio requirements and limitations for <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Deploying <span class=\"ph\">Agent Cloud<\/span> with Microsoft Copilot Studio requires specific         components, administrator roles, API access, and table permissions across the Azure and             <span class=\"ph\">Agent Cloud<\/span> environments. A Copilot Studio limitation causes             <span class=\"ph\">Agent Cloud<\/span> to display conversations only after 30 minutes of inactivity.<\/p>","href":"agent_cloud\/ms_copilot_studio_requirements_limitations_agent_cloud.html","attributes":{"data-id":"ms_copilot_studio_requirements_limitations_agent_cloud"},"menu":{"hasChildren":false},"tocID":"ms_copilot_studio_requirements_limitations_agent_cloud-d36754e60161","topics":[]},{"title":"Deploying Microsoft Copilot Studio to <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Deploy Microsoft Copilot Studio to <span class=\"ph\">Agent Cloud<\/span> to enable agent discovery,         activity logging, and real-time tool blocking.<\/p>","href":"agent_cloud\/deploying_ms_copilot_studio.html","attributes":{"data-id":"deploying_ms_copilot_studio"},"menu":{"hasChildren":false},"tocID":"deploying_ms_copilot_studio-d36754e60183","next":"deploying_ms_copilot_studio-d36754e60183"},{"title":"Enabling tool blocking on <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Enable tool blocking so that Microsoft Copilot Studio intercepts and blocks         unauthorized tool usage and policy violations in real-time using <span class=\"ph\">Agent Cloud<\/span>.<\/p>","href":"agent_cloud\/enabling_tool_blocking.html","attributes":{"data-id":"enabling_tool_blocking"},"menu":{"hasChildren":false},"tocID":"enabling_tool_blocking-d36754e60213","topics":[]}]}};